import XCTest
@testable import Dropshot

final class DropSettingsTests: XCTestCase {
    /// Generated by the Worker's `hashPassword("correct horse")` with the salt bytes 0 to 15.
    func testPasswordHashMatchesWorker() {
        let salt = Data((0..<16).map { UInt8($0) })

        XCTAssertEqual(
            PasswordHash.make("correct horse", salt: salt),
            "pbkdf2$100000$AAECAwQFBgcICQoLDA0ODw==$V/LC8HOXSNUWQZsGKohGZjI8WD6krhZVBKgfe1PGKgk="
        )
    }

    func testPasswordDropSendsHashNotPlaintext() throws {
        let now = Date(timeIntervalSince1970: 1_000)
        let metadata = DropSettings(privacy: .password, password: "hunter22", selfDestruct: .oneHour, allowDownload: false).metadata(now: now)

        XCTAssertEqual(metadata["privacy"], "password")
        XCTAssertEqual(metadata["allow-download"], "0")
        XCTAssertEqual(metadata["expires-at"], "4600000")
        XCTAssertTrue(try XCTUnwrap(metadata["password-hash"]).hasPrefix("pbkdf2$100000$"))
        XCTAssertFalse(metadata.values.contains { $0.contains("hunter22") })
    }

    func testInvalidPasswordFallsBackToPublic() {
        let metadata = DropSettings(privacy: .password, password: "abc", selfDestruct: .keep, allowDownload: true).metadata()

        XCTAssertEqual(metadata["privacy"], "public")
        XCTAssertNil(metadata["password-hash"])
        XCTAssertNil(metadata["expires-at"])
        XCTAssertEqual(metadata["allow-download"], "1")
    }
}
